"""Read-only synthetic SESSION-001 characterization from an explicit Git export."""
import asyncio
from dataclasses import asdict
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys


async def capture(source, revision):
    root = Path.cwd().resolve()
    env = dict(os.environ, GIT_OPTIONAL_LOCKS='0')
    git = lambda *a: subprocess.check_output(['git', '-C', str(root), *a], env=env)
    revision = git('rev-parse', '--verify', revision + '^{commit}').decode().strip()
    expected = {}
    for line in git('ls-tree', '-r', revision, '--', 'packages').decode().splitlines():
        header, name = line.split('\t', 1)
        if '/src/' in name:
            expected[name] = header.split()[2]
    actual = {str(f.relative_to(source)): f for tree in (source / 'packages').glob('*/src') for f in tree.rglob('*') if f.is_file()}
    if set(actual) != set(expected):
        raise RuntimeError('Source inventory differs from Git')
    for name, blob in expected.items():
        if actual[name].read_bytes() != git('cat-file', 'blob', blob):
            raise RuntimeError('Source byte drift: ' + name)
    roots = [f.resolve() for f in sorted((source / 'packages').glob('*/src'))]
    sys.path[:0] = [str(f) for f in roots]

    import importlib.util
    import importlib
    from dataclasses import asdict
    from types import SimpleNamespace as NS
    from unittest.mock import patch
    from friday_chat.commands.contracts import CommandContext, CommandMetadata, CommandResult
    from friday_chat.commands import registry as reg
    from friday_chat.commands.registry import CommandRegistry, build_default_registry
    rows = []
    marker = CommandMetadata('unused', 'Unused', 'unused', '/unused')
    export_owner = importlib.import_module('friday_chat.commands.diagnostics') if importlib.util.find_spec('friday_chat.commands.diagnostics') else reg
    destination = Path(sys.argv[2]).parent / (Path(sys.argv[2]).stem + '-exports')
    if destination.exists():
        raise RuntimeError('Use a fresh export destination')
    destination.mkdir()
    events = []
    class Trace:
        def __init__(self, label, **values):
            object.__setattr__(self, '_label', label)
            self.__dict__.update(values)
        def __getattribute__(self, name):
            if not name.startswith('_'):
                events.append(object.__getattribute__(self, '_label') + '.' + name)
            return object.__getattribute__(self, name)
    class Memory:
        def __init__(self, diagnostics=None, failure=None, entered=None, release=None):
            self.diagnostics, self.failure, self.entered, self.release = diagnostics, failure, entered, release
        async def debug_retrieval(self, query):
            events.append('memory.debug_retrieval:' + query)
            if self.entered is not None:
                self.entered.set()
                await self.release.wait()
            if self.failure is not None:
                raise self.failure
            return self.diagnostics
    turn = NS(turn_ref='turn-2', outcome='ok', persistence='stored', completed_tools=2, failed_tools=0, duration_ms=1234.5)
    execution = NS(turns=(NS(turn_ref='ignored'), turn), counters=(('z', 'ok', 3), ('a', 'failed', 1)))
    def runtime(*, memory=None, telemetry=False, window=1000, buffer=100):
        return Trace('runtime', tool_context='Tools: echo', memory=memory, telemetry=Trace('telemetry', execution_snapshot=lambda: (events.append('execution_snapshot') or execution)) if telemetry else None,
                     config=Trace('config', memory=Trace('budget', context_window=window, output_buffer=buffer), chat=Trace('chat', system_prompt='Friday system'), transcript=NS(export_directory=str(destination))))
    def context(**values):
        defaults = dict(runtime=None, history=[('user\n二', 'answer')], last_context=None, last_prompt=None, last_debug={}, last_timing={}, exit_requested=False)
        defaults.update(values)
        return Trace('context', **defaults)
    def normalize(value):
        if isinstance(value, str):
            return value.replace(str(destination), '$EXPORT')
        if isinstance(value, dict):
            return {k: normalize(v) for k,v in value.items()}
        if isinstance(value, (list, tuple)):
            return [normalize(v) for v in value]
        return value
    async def run(label, name, ctx, args=(), failure=None):
        events.clear()
        row = {'case': label, 'command': name, 'args': list(args)}
        before = {p.name:p.read_text() for p in destination.iterdir()}
        try:
            result = await getattr(reg, '_' + name.replace('-', '_') + '_handler')(ctx, args, marker)
            row['result'] = asdict(result)
        except BaseException as error:
            row['exception'] = {'type':type(error).__name__, 'message':str(error)}
            if failure is not None:
                row['exception']['same_object'] = error is failure
        row['events'] = list(events)
        row['files_before'] = before
        row['files_after'] = {p.name:p.read_text() for p in destination.iterdir()}
        rows.append(normalize(row))
    for name in ('context', 'prompt'):
        for label, value in [('none', None), ('empty', ''), ('cached', 'stored\nÅ text')]:
            await run(name + ':' + label, name, context(**{'last_'+name:value}), ('ignored',))
        await run(name + ':fallback-runtime', name, context(runtime=runtime()), ())
    for name in ('context','prompt'):
        for label, value in [('falsy-int',0),('falsy-list',[]),('truthy-int',7),('truthy-list',['x'])]:
            await run(name+':undeclared-cache:'+label,name,context(**{'last_'+name:value}))
    for args in [('--debug',), ('--debug','--debug','ignored'), ('--DEBUG',), ('--file','--debug'), ('--file',)]:
        await run('context:flags:' + ','.join(args), 'context', context(runtime=runtime(),last_context='Å\ntext'), args)
    await run('prompt:export', 'prompt', context(runtime=runtime(),last_prompt='exact prompt\n'), ('--file','--file','../ignored'))
    await run('prompt:overwrite', 'prompt', context(runtime=runtime(),last_prompt='replacement'), ('--file',))
    for name in ('context','prompt'):
        failure = OSError('synthetic export failure')
        def fail(*args):
            events.append('write_export')
            raise failure
        with patch.object(export_owner, '_write_export_file', fail):
            await run(name+':export-failure', name, context(**{'last_'+name:'cached'}), ('--file',), failure)
    for name, field, values in [('debug','last_debug',{'z':'last','a':'first'}), ('timing','last_timing',{'z':0.0,'a':0.12555})]:
        await run(name+':empty',name,context(),('ignored',))
        await run(name+':fields',name,context(**{field:values}),('ignored',))
        await run(name+':telemetry',name,context(runtime=runtime(telemetry=True),**{field:values}))
        await run(name+':telemetry-only',name,context(runtime=runtime(telemetry=True)))
        await run(name+':no-telemetry',name,context(runtime=runtime(),**{field:values}))
        await run(name+':mixed-keys',name,context(**{field:{'a':1,2:2}}))
    await run('timing:invalid-value','timing',context(last_timing={'bad':'not-a-number'}))
    await run('debug:formatted-values','debug',context(last_debug={'none':None,'flag':False,'items':['x']}))
    for label, rt in [('none',None), ('configured',runtime()), ('zero',runtime(window=0,buffer=0)), ('truthy-text',runtime(window='many',buffer='few')), ('negative',runtime(window=-1,buffer=-2))]:
        await run('budget:'+label,'debug-budget',context(runtime=rt),('ignored',))
    rt=runtime(); rt.config.memory=None
    await run('budget:memory-none','debug-budget',context(runtime=rt))
    await run('retrieval:runtime-before-usage','debug-retrieval',context())
    await run('retrieval:usage','debug-retrieval',context(runtime=runtime()))
    for label, diagnostics in [('empty',{}), ('details',{'snippets':['one\n two', {'x':1}, 'x'*170]*4,'debug_info':{'z':None,'a':False}}), ('wrong-containers',{'snippets':('ignored',),'debug_info':['ignored']}), ('dict-subclass',type('D',(dict,),{})({'snippets':[], 'debug_info':{'b':2,'a':1}})), ('mixed-keys',{'debug_info':{'a':1,2:2}}), ('none',None)]:
        await run('retrieval:'+label,'debug-retrieval',context(runtime=runtime(memory=Memory(diagnostics))), ('hello','"quoted','world"'))
    for label, failure in [('exception',RuntimeError('retrieval failed')),('cancel',asyncio.CancelledError('cancelled'))]:
        await run('retrieval:'+label,'debug-retrieval',context(runtime=runtime(memory=Memory(failure=failure))), ('q',),failure)
    entered, release = asyncio.Event(), asyncio.Event()
    memory = Memory({}, entered=entered, release=release)
    events.clear()
    task=asyncio.create_task(reg._debug_retrieval_handler(context(runtime=runtime(memory=memory)),('wait',),marker))
    try:
        await asyncio.wait_for(entered.wait(),5)
        during={'task_done':task.done(),'events':list(events)}
        release.set(); result=await asyncio.wait_for(task,5)
        rows.append({'case':'retrieval:await','during':during,'result':asdict(result),'events':list(events)})
    finally:
        if not task.done():
            task.cancel()
            try: await task
            except asyncio.CancelledError: pass
    registry=build_default_registry()
    for text in ['/CONTEXT --debug extra','/prompt extra','/debug ignored','/debug-budget extra','/timing extra','/debug-retrieval','/debug-retrieval "a b" c',' /debug','//context','/ context']:
        ctx=CommandContext()
        handled,result=await registry.execute(text,ctx)
        rows.append({'case':'dispatch:'+text,'handled':handled,'result':None if result is None else asdict(result)})
    for name in ('context','prompt','debug','debug-budget','timing','debug-retrieval'):
        custom=CommandRegistry()
        async def own(*args): return CommandResult(output='custom')
        custom.register(name,description='Custom',category='custom',handler=own)
        handled,result=await custom.execute('/'+name,CommandContext())
        rows.append({'case':'custom:'+name,'handled':handled,'result':asdict(result)})
    origins={}
    for name,module in tuple(sys.modules.items()):
        if name.startswith('friday') and module is not None:
            paths=([module.__file__] if getattr(module,'__file__',None) else []) + list(getattr(module,'__path__',()))
            if not paths or not all(any(Path(p).resolve().is_relative_to(tree) for tree in roots) for p in paths):
                raise RuntimeError('Loaded module escaped source export: '+name)
            origins[name]=[str(Path(p).resolve()) for p in paths]
    return {'provenance':{'revision':revision,'capture_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'source_files':len(actual),'source_inventory_sha256':hashlib.sha256(json.dumps(expected,sort_keys=True).encode()).hexdigest(),'origins':origins},'metadata':{name:asdict(registry.commands[name]) for name in ('context','prompt','debug','debug-budget','timing','debug-retrieval')},'cases':rows}

if __name__ == '__main__':
    source, output, revision = Path(sys.argv[1]).resolve(), Path(sys.argv[2]).resolve(), sys.argv[3]
    if output.exists() or output.is_relative_to(Path.cwd().resolve()) or output.is_relative_to(source):
        raise SystemExit('Use a fresh output outside repository and export')
    output.write_text(json.dumps(asyncio.run(capture(source,revision)),indent=2)+'\n')
    print('Captured diagnostics cases')

