"""Exact JSON diagnostics comparison with pinned baseline/capture identities."""
import copy
import hashlib
import json
from pathlib import Path
import sys

def same(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(same(left[k], right[k]) for k in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(same(a,b) for a,b in zip(left,right,strict=True))
    return left == right

def compare(raw, candidate, baseline_sha, capture_sha, allow_cache_refusal=False):
    if hashlib.sha256(raw).hexdigest() != baseline_sha:
        raise ValueError('Baseline hash mismatch')
    base = json.loads(raw)
    for document in (base, candidate):
        if document['provenance']['capture_sha256'] != capture_sha:
            raise ValueError('Capture identity mismatch')
    if not same(base['metadata'],candidate['metadata']):
        raise ValueError('Diagnostics differ: metadata')
    if len(base['cases']) != len(candidate['cases']):
        raise ValueError('Diagnostics row count differs')
    exceptions = {name+':undeclared-cache:'+kind for name in ('context','prompt') for kind in ('truthy-int','truthy-list')}
    for old, new in zip(base['cases'],candidate['cases'],strict=True):
        if same(old,new):
            continue
        if allow_cache_refusal and old['case'] in exceptions:
            expected = copy.deepcopy(old)
            del expected['result']
            expected['exception'] = {'type':'TypeError'}
            observed = copy.deepcopy(new)
            if isinstance(observed.get('exception'),dict):
                observed['exception'].pop('message',None)
            if same(expected,observed):
                continue
        raise ValueError('Diagnostics differ: '+old['case'])

def selftest():
    b={'provenance':{'capture_sha256':'program'},'metadata':{'name':'context'},'cases':[{'case':'control','flag':False,'n':0,'events':['read','write']}]}
    raw=json.dumps(b).encode(); digest=hashlib.sha256(raw).hexdigest()
    compare(raw,b,digest,'program')
    controls=[]
    for label in ('baseline','program','bool-int','row','order','metadata','extra'):
        v=copy.deepcopy(b); r=raw
        if label=='baseline': r += b' '
        elif label=='program': v['provenance']['capture_sha256']='other'
        elif label=='bool-int': v['cases'][0]['flag']=0
        elif label=='row': v['cases'][0]['n']=1
        elif label=='order': v['cases'][0]['events'].reverse()
        elif label=='metadata': v['metadata']['name']='prompt'
        elif label=='extra': v['cases'].append({})
        try: compare(r,v,digest,'program')
        except ValueError: controls.append(label)
        else: raise RuntimeError('Comparator accepted '+label)
    boundary=copy.deepcopy(b)
    boundary['cases']=[{'case':'context:undeclared-cache:truthy-int','result':{'output':7},'events':['context.last_context']}]
    raw2=json.dumps(boundary).encode(); sha2=hashlib.sha256(raw2).hexdigest()
    refusal=copy.deepcopy(boundary)
    del refusal['cases'][0]['result']
    refusal['cases'][0]['exception']={'type':'TypeError','message':'Expected a string'}
    compare(raw2,refusal,sha2,'program',True)
    for label, allow, candidate in [('boundary-without-approval',False,refusal),('wrong-boundary-exception',True,copy.deepcopy(refusal)),('boundary-side-effect',True,copy.deepcopy(refusal))]:
        if label=='wrong-boundary-exception': candidate['cases'][0]['exception']['type']='ValueError'
        if label=='boundary-side-effect': candidate['cases'][0]['events'].append('write')
        try: compare(raw2,candidate,sha2,'program',allow)
        except ValueError: controls.append(label)
        else: raise RuntimeError('Comparator accepted '+label)
    print('Comparator refused:', ', '.join(controls))

if __name__=='__main__':
    if sys.argv[1:] == ['--selftest']:
        selftest()
    else:
        args=sys.argv[1:]
        allow=args[-1:] == ['--allow-declared-cache-refusal']
        if allow: args=args[:-1]
        baseline,candidate,digest,program = args
        compare(Path(baseline).read_bytes(),json.loads(Path(candidate).read_text()),digest,program,allow)
        print('Six metadata records and all diagnostic cases match exactly')

